#!/usr/bin/env bash
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing final-freeze script..."
decode "scripts/ntc_final_freeze.py" << 'B64EOF'

B64EOF
echo "Installed. Run:  python scripts/ntc_final_freeze.py"